) AS (
  VALUES 
    (514::BIGINT, 'Las clases presenciales del curso son meh, eso sí, si no le pone atención en esas clases y no toma los apuntes que debe, vea a ver de donde se saca la materia porque el no deja ninguna referencia al respecto, únicamente lo hace para las clases virtuales, tiene que saber programar bien.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-08-07T00:00:00+00:00'::TIMESTAMPTZ, '94a3c87b534257213aed73ad88b67dc813a58f7c98fcb7491fb57dc2cd421c7e'::TEXT, ARRAY[3003]::BIGINT[]),
    (514::BIGINT, 'El curso no me gustó, siento que el profe si explica bien y todo solo si las evaluaciones fueran teóricas, la parte de progra estuvo un poco más enredada. Mi única queja real es que el profe escribe medio raro y pequeño, casi no entendía que escribía en la pizarra.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2026-07-18T00:00:00+00:00'::TIMESTAMPTZ, 'b70351bc4b5f47269bd94579ef9f4f1e2005fa238abef2db7d12e92113788902'::TEXT, ARRAY[3003]::BIGINT[]),
    (514::BIGINT, 'Profe me encantas y con ese último comentario aquí, estoy feliz… será que ya te estás haciendo como Masís?… Profe, prometo que no seré como las amantes de Masís, a su esposa no le diré nada… ja ja ja… pero sea como Masís y caiga en la infidelidad conmigo…'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2026-04-17T00:00:00+00:00'::TIMESTAMPTZ, 'eabde97d516a00e580d722cc6b6e4bfcff4a47755893ba27f6e7ebd666be0aac'::TEXT, ARRAY[1018, 2439]::BIGINT[]),
    (514::BIGINT, 'Se le notan las preferencias Ayuda solo al que le cae bien y mas si sos mujer'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-02-12T00:00:00+00:00'::TIMESTAMPTZ, '2bd1a9f7f51de8f4723a20bb86bf64a9c9dce59e1577b41837743ac4eec91ca8'::TEXT, ARRAY[2439]::BIGINT[]),
    (514::BIGINT, 'Excelente profesor, las clases son muy claras y no se pierde dando la materia, el curso por naturaleza es aburrido, pero el lo hace entretenido ya que te pone a practicar y eso te obliga a estar atento, llevaría mas cursos con el sin duda alguna, además no califica duro y sus evaluaciones son claras'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2025-12-24T00:00:00+00:00'::TIMESTAMPTZ, '83dc3d00cd26795a2b628b15f318de8d2703df7aae2bfa342ee718db533c6722'::TEXT, ARRAY[103]::BIGINT[]),
    (514::BIGINT, 'Excelente profe. Da bastante bien las clases, siempre está disponible para consultas. Los exámenes son fáciles si lleva la materia al día y sabe lo básico de progra. Se nota que sabe mucho, y le interesa enseñar la materia,y que los estudiantes aprendan'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2025-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'fbcb3bbe6fbddfea654520738a9ac539a50ec720e4ec6f28298b3003186e7a78'::TEXT, ARRAY[3003]::BIGINT[]),
    (514::BIGINT, 'Es un profe muy serio y estricto con lo que pide, pero realmente explica muy bien y las asignaciones es de poner atención en clases e investigar un poco. Los exámenes son largos pero con estudiar los ejercicios de la práctica que deja se pasan faciles. Es bastante intimidante, pero es buen profe'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas']::TEXT[], '2025-07-21T00:00:00+00:00'::TIMESTAMPTZ, '898a7d3f2cf45dd4f0bf82e4b744dc2174fc4442938582f87a731798a8119a77'::TEXT, ARRAY[3003]::BIGINT[]),
    (514::BIGINT, 'Buen profe, se entiende bien los temas, con que vaya a clases, haga las tareas que deja y se prepare bien para los exámenes, todo va a salir bien'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-12-06T00:00:00+00:00'::TIMESTAMPTZ, '8e09eb9c32c6a2199da45f612a3af7a8dc1f2d8488c0c75f899eeb35c06d6441'::TEXT, ARRAY[3003]::BIGINT[]),
    (514::BIGINT, 'El profe es muy bueno pero la clase puede ser un poco lenta, le gusta programas en la clase entonces se aprende bien esa parte pero cuando se encuentra un error quita un poco el dinamismo. Aun así explica muy bien y siempre esta atento a dudas. Los proyectos son largos pero fáciles'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2024-12-02T00:00:00+00:00'::TIMESTAMPTZ, '432839125d107c1e3e1217dc26ced597fab06bc571550205d44a1ef723c074c0'::TEXT, ARRAY[1335]::BIGINT[]),
    (514::BIGINT, 'Excelente profesor. Tiene paciencia para dar la clase y explica súper bien. Si hace los ejercicios que el deja le va muy bien en el examen.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2024-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'e5bce4383d7296929a2b1c76b7a9745b7d633724413f31ecd91280c2f554eede'::TEXT, ARRAY[2439]::BIGINT[]),
    (514::BIGINT, 'Es un excelente profe, sabe de lo que habla, más que es matemático. Las clases no son pesadas, los exámenes los hace apartir de los ejercicios de práctica y siempre está dispuesto a responder las dudas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-18T00:00:00+00:00'::TIMESTAMPTZ, '0c01c8d465dfbf018c67ebb1cdb367466a34cc20692e573ddb6aa62156a71f78'::TEXT, ARRAY[2978]::BIGINT[]),
    (514::BIGINT, 'Explica la materia bien pero los laboratorios y las tareas las califica estricto, para los examenes hay que estudiar todo e ir bien reparado'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-12-14T00:00:00+00:00'::TIMESTAMPTZ, 'c7d465a0eaa6fe9978a6c2835aab40f1453a414cb2c8012309d2b862820a6466'::TEXT, ARRAY[3003]::BIGINT[]),
    (514::BIGINT, 'Muy satisfecho, claro, buena gente, comprensivo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2022-06-14T00:00:00+00:00'::TIMESTAMPTZ, '211e5a4db3cdafa98ec96d0aef3c0b58088df6efb575ac201f72efbf13ca8596'::TEXT, ARRAY[3003]::BIGINT[]),
    (514::BIGINT, 'Es muy bueno realmente, las clases son muy puntuales (se ve lo que se ocupa) pero si hay que ponerle. Deja muchas tareas y es muy estricto con las instrucciones, sin embargo no son tan dificiles. Consejo: vaya al día y si tiene dudas escribale que de fijo le ayuda (evite fines de semana).'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Muchas tareas']::TEXT[], '2021-12-01T00:00:00+00:00'::TIMESTAMPTZ, 'b32fd4d6f695d9e57f3298e8a193380cce84f9939dc22069a0832e259b06e70b'::TEXT, ARRAY[3003]::BIGINT[]),
    (514::BIGINT, 'Pésimo la verdad. Mucha atención a las instrucciones porque por una coma que uno falle no le revisa. Clases mediocres. Lo único que le rescato es que se aprende por las tareas (que uno hace, no nada que él enseñe).'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2021-11-30T00:00:00+00:00'::TIMESTAMPTZ, 'b7b6f87e19813c7c9957ec8a08f90c3f260a8e3de4752756bf5b356c6bc22666'::TEXT, ARRAY[3003]::BIGINT[]),
    (514::BIGINT, 'El profesor ayuda bastante si uno tiene dudas y explica muy bien. Lo que pasa es que sus clases son un poco inútiles ya que quien explica la teoría son los videos de la cátedra. El curso es complicado pero si se hacen las consignas se hace fácil.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2021-06-29T00:00:00+00:00'::TIMESTAMPTZ, '4d92a3e77e0042ddefb39511c720b247f4b28bdc7a1f01b877ed30e499f82177'::TEXT, ARRAY[103]::BIGINT[]),
    (514::BIGINT, 'El profe sabe mucho del tema y explica bien, se aprende bastante con las tareas y el catalogo . Es bastante amable.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-12T00:00:00+00:00'::TIMESTAMPTZ, '9c8f664b5b181cdd04e6c653b946d7b941bf6e1335341db6784cbace0ff72e6b'::TEXT, ARRAY[3003]::BIGINT[]),
    (514::BIGINT, 'Es buen profe, a veces es un poco desordenado y se enreda pero atiende en hora de consulta y le interesa bastante que los estudiantes aprendan.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-02-12T00:00:00+00:00'::TIMESTAMPTZ, '5d257b2f73b5c03662dde58ca74f5f1871e715750505a9d1d3169cf24cf781bf'::TEXT, ARRAY[1049]::BIGINT[]),
    (514::BIGINT, 'Hay que ponerle bastante y estudiar muchísimo. El curso quita mucho tiempo. El profe a veces se enreda solo pero es muy pura vida y ayuda si uno lo necesita. Bastante desordenado y a veces cuesta que conteste correos.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-28T00:00:00+00:00'::TIMESTAMPTZ, 'd86931db7f0dff444f2207819702f663c331d210a0561e213c1c570c1000e988'::TEXT, ARRAY[1049]::BIGINT[]),
    (514::BIGINT, '(modalidad virtual) un profesor excelente, siempre dispuesto a aclarar dudas. Muy conveniente que utilice una tableta para dar la clase, especialmente por los apuntes.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-01-28T00:00:00+00:00'::TIMESTAMPTZ, 'fe1da68792279cc22a253c2f1e0a84f8e17022d3f526779c17531e45a17944e3'::TEXT, ARRAY[1049]::BIGINT[]),
    (514::BIGINT, 'Es uno de los mejores profes de mate que he tenido, explica bien y se interesa en que todos los estudiantes aperndan. Tienen que estudiar bastante y hacer los quices.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, 'dc82fccb90c50856dd9c25b14dd53be3ac0e805b8b0d034334c65fba7ffc7e20'::TEXT, ARRAY[2439]::BIGINT[]),
    (514::BIGINT, 'Es un súper profesor, explica demasiado bien y se preocupa un montón porque uno aprenda. Aunque sí, las clases tal vez puedan ser un poco aburridas, pero si usted pone atencion no es posible que salga con dudas.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-02-14T00:00:00+00:00'::TIMESTAMPTZ, 'b1c2de926d83c053c42bd1bf97dc88cdff2367a88f95c54d37bc8a59ee271962'::TEXT, ARRAY[1018]::BIGINT[]),
    (514::BIGINT, 'Es buen profe una buena nota, el problema es que las clases son algo aburridas y se hacen largas, aunque nos sacaba antes. Deja muchas tareas y hay catalogo que se entrega cada quincena. Califica duro exámenes escritos. Para repo no se la deja fácil.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2020-02-03T00:00:00+00:00'::TIMESTAMPTZ, 'fe0d3a90f1b7943c5fa5beb3e04c14f2c6ddd76625d71b1eaf68ed35e99a3a4b'::TEXT, ARRAY[3003]::BIGINT[]),
    (514::BIGINT, 'Es un gran profesor, deja tareas todo el tiempo y hay quices semanales pero eso ayuda muchísimo a practicar y al final lo beneficia a uno. De verdad se ve que le interesa que los estudiantes aprendan y si hay dudas él con mucho gusto las aclara. Lo recomendable es ir a consulta tambíen con él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'b7a4052375514b9d8b056aa82e2d2e871cf58e89778db0674699658beba07d5a'::TEXT, ARRAY[2439]::BIGINT[]),
    (514::BIGINT, 'Es muy buena gente, se preocupa por el aprendizaje de los estudiantes. Hay que poner demasiada atención, hace quices todas las semanas y siempre manda un montón de ejercicios de tarea, los más difíciles los toma como parte de la nota para el quiz.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2019-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'cafb96de82037efb48af7ca1ccae762770f7aec528d1bb4e3ddcf8573bb651da'::TEXT, ARRAY[2439]::BIGINT[]),
    (514::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-24T00:00:00+00:00'::TIMESTAMPTZ, '8538361e95f074c275941a7fe02d0df5befd49c14c8ddcc2a97cb8803ae193e5'::TEXT, ARRAY[2439]::BIGINT[]),
    (514::BIGINT, 'Buen profe y buena nota, se pasa fácil solo con estudiar de las presentaciones que él da. También hace varias clases en el lab para que los conceptos queden claros en programación.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas', 'Aspectos de calificación claros']::TEXT[], '2019-06-19T00:00:00+00:00'::TIMESTAMPTZ, '90fb464c1bb4d1fd6288fb41aa2b731bfaac647c79d612a826eaf115a11ad3f9'::TEXT, ARRAY[3003]::BIGINT[]),
    (514::BIGINT, 'Es muy buen profe y sabe mucho. Es muy justo y claro en las instrucciones que da. Las clases son terriblemente aburridas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos']::TEXT[], '2019-06-19T00:00:00+00:00'::TIMESTAMPTZ, '0955861dbbab282d41845ba9fdbb506fab31ae45cdebd3252015937cfaa2135f'::TEXT, ARRAY[3003]::BIGINT[]),
    (514::BIGINT, 'La clase es MUY/DEMASIADO aburrida. Es un buen matemático pero en la parte de progra está muy perdido. Deja tareas que al final no le ayudan a uno en nada a entender. Literal el dá en clases lo mismo de las presentaciones. Exámenes de parte teórica fácil y la progra le toca a uno investigar.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Muchos proyectos grupales']::TEXT[], '2019-06-19T00:00:00+00:00'::TIMESTAMPTZ, '9db3c0fc7664b55c303b0d8c38877d1a5dc08b5253df7ad311d8b73799dc66c1'::TEXT, ARRAY[3003]::BIGINT[]),
    (514::BIGINT, 'Demasiado buen profe. En serio se preocupa que sus estudiantes aprendan. Resuelve todas las dudas de la mejor manera y no va avanzar hasta que todos hayan entendido. Hace quiz cada semana pero es de gran utilidad luego para el examen. Explica demasiado bien la materia. Y suele subir practicas extra.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-13T00:00:00+00:00'::TIMESTAMPTZ, '70106a9f980ef185766fcc7f194e61d7854ce39d121168fc08b8a4b31c2cb124'::TEXT, ARRAY[2439]::BIGINT[]),
    (514::BIGINT, 'Una teja de profesor. Me enseñó a no temerle a la matemática. Explica paso por paso y con mucha paciencia. Si tienen la gran oportunidad de meter con él, no lo duden.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2019-06-10T00:00:00+00:00'::TIMESTAMPTZ, '8cc1d04eddfe5774e9239dc02ad18b7a296633fd50b2227e55a00d2a880cedfb'::TEXT, ARRAY[2439]::BIGINT[]),
    (514::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-05-30T00:00:00+00:00'::TIMESTAMPTZ, 'cb02eec652a5848bddeab0c1e3b5b47bd81ab73e59bcb52c24d6f5e00a87c27a'::TEXT, ARRAY[2439]::BIGINT[]),
    (514::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-05-29T00:00:00+00:00'::TIMESTAMPTZ, 'e2aeec80fcf39f6a68088f366f9e1bd2048fd6f0bb17605d76af88c5b85f4888'::TEXT, ARRAY[2439]::BIGINT[]),
    (514::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-25T00:00:00+00:00'::TIMESTAMPTZ, '3cc612ad6ac8cbefa4c39b21347370498ebdfa3703cd25b4e4ce921308ab367d'::TEXT, ARRAY[1641]::BIGINT[]),
    (514::BIGINT, 'Excelente profe'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases excelentes']::TEXT[], '2018-06-24T00:00:00+00:00'::TIMESTAMPTZ, '9e9c96dafd271a4c562aea59b4bb946f117359d77ac31c09fea82f8d9ac82e27'::TEXT, ARRAY[1641]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
